// aliases either input.
//
//   - nil + nil -> nil
//   - nil + x   -> copy of x
//   - x + y     -> x + y
func AddCostUSD(a, b *float64) *float64 {
	if a == nil && b == nil {
		return nil
	}
	var sum float64
	if a != nil {
		sum += *a
	}
	if b != nil {
		sum += *b
	}
	return &sum
}

