// (see firstMeaningfulLine); checkpoint_transcript_start falls back to the
// deprecated transcript_lines_at_start.
func parseSession(metaJSON, promptTxt []byte) (parsedSession, bool) {
	var m committedMetadata
	if err := json.Unmarshal(metaJSON, &m); err != nil {
		return parsedSession{}, false
	}
	agent := m.Agent
	if agent == "" {
		agent = legacyFallbackAgent
	}
	steps := m.CheckpointsCount
	if steps == 0 {
		steps = 1
	}
	start := m.CheckpointTranscriptStart
	if start == nil {
		start = m.TranscriptLinesAtStart
	}
	si := store.SessionInfo{
		Prompt:                      firstMeaningfulLine(promptTxt),
		Agent:                       agent,
		Model:                       m.Model,
		Kind:                        m.Kind,
		Steps:                       steps,
		SessionID:                   m.SessionID,
		CreatedAt:                   m.CreatedAt,
		TranscriptIdentifierAtStart: m.TranscriptIdentifierAtStart,
		CheckpointTranscriptStart:   start,
	}
	rawSkillEvents := m.SkillEvents
	if rawSkillEvents == nil {
		rawSkillEvents = m.SkillEventsCamel
	}
	si.SkillEvents = transcript.NormalizeSkillEvents(rawSkillEvents)
	if tu := m.TokenUsage; tu != nil {
		si.TokenUsage = mapTokenCounts(*tu)
	}
	// Cost per bucket PREFERS the cost the CLI already reported and only estimates
	// server-side when the bucket carries none (see bucketCost for why: the CLI
	// priced the tokens against the rates in force when they were spent, and the
	// platform has no price history to reconstruct that for an old checkpoint).
	// A reported bucket is taken verbatim and stamped "reported"; an unreported one
	// is priced cache-accurately from its four token fields and stamped "estimated".
	// The per-bucket costs sum into the session cost, whose source collapses to the
	// single shared label or "mixed" when the session spans both. An unknown model
	// with no reported cost prices to nil (never guess), matching the CLI's semantics.
	if len(m.ModelUsage) > 0 {
		mus := make([]store.ModelUsage, 0, len(m.ModelUsage))
		var sessionCost float64
		var priced bool
		costSources := map[string]struct{}{}
		for _, mu := range m.ModelUsage {
			stu := mapTokenCounts(mu.TokenUsage)
			if c, src := bucketCost(mu.Model, mu.TokenUsage); c != nil {
				stu.CostUSD = c
				stu.CostSource = src
				sessionCost += *c
				priced = true
				costSources[src] = struct{}{}
			}
			mus = append(mus, store.ModelUsage{Model: mu.Model, TokenUsage: *stu})
		}
		si.ModelUsage = mus
		applySessionCost(&si, sessionCost, priced, costSources)
	} else if si.TokenUsage != nil {
		// No per-model breakdown: take the session-level reported cost, else price the
		// aggregate token_usage against its single model id. bucketCost already
		// range-validates either result.
		if c, src := bucketCost(m.Model, *m.TokenUsage); c != nil {
			si.TokenUsage.CostUSD = c
			si.TokenUsage.CostSource = src
		}
	}
	if a := m.InitialAttribution; a != nil {
		si.Attribution = mapAttribution(a)
	}
	return parsedSession{
		Info:                        si,
		TranscriptIdentifierAtStart: m.TranscriptIdentifierAtStart,
		TranscriptLinesAtStart:      m.TranscriptLinesAtStart,

