// TestParseSessionTrustsAnyCLICostLabel proves a valid cost_usd from the CLI is
// trusted regardless of its cost_source string. The label is CLI-internal
// provenance ("reported" for agent-billed, "estimated" for the CLI's own
// token-based calculation, anything else for an unrecognised/absent tag) about
// *how* the CLI arrived at the number, not a signal for whether the platform
// should trust it: every case here was priced by the CLI at the rates in force
// when the tokens were spent, so all are equally authoritative and all collapse
// to store.CostSourceReported (meaning "sourced from the client") here.
func TestParseSessionTrustsAnyCLICostLabel(t *testing.T) {
	for _, tc := range []struct {
		name       string
		costSource string
	}{
		{"source is the CLI's own estimate", `"estimated"`},
		{"source is an unrecognised label", `"provider-api"`},
		{"source absent", `""`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			meta := `{"session_id":"s","agent":"claude","checkpoints_count":1,
				"model_usage":[
					{"model":"claude-sonnet-5","token_usage":{"input_tokens":1000000,"output_tokens":1000000,` +
				`"cost_usd":123.45,"cost_source":` + tc.costSource + `}}
				]}`
			ps, ok := parseSession([]byte(meta), nil)
			if !ok {
				t.Fatal("parseSession failed")
			}
			mu := ps.Info.ModelUsage[0].TokenUsage
			if mu.CostUSD == nil || *mu.CostUSD != 123.45 || mu.CostSource != "reported" {
				t.Errorf("bucket cost = %+v/%q, want 123.45/reported (any valid CLI cost is trusted)", mu.CostUSD, mu.CostSource)
			}
		})
	}
}

// TestParseSessionUnusableReportedCostFallsBackToEstimate proves a cost_usd the
// NUMERIC(14,6) column can't hold (negative, non-finite, >= 1e8) re-prices here
// instead of being persisted — it would fault the INSERT and poison-loop the
// consumer. claude-sonnet-5: 1M in + 1M out = $18.00.
func TestParseSessionUnusableReportedCostFallsBackToEstimate(t *testing.T) {
	for _, tc := range []struct {
		name       string
		costUSD    string
		costSource string
	}{
		{"value negative", "-1.0", `"reported"`},
		{"value over column range", "100000000.0", `"reported"`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			meta := `{"session_id":"s","agent":"claude","checkpoints_count":1,
				"model_usage":[
					{"model":"claude-sonnet-5","token_usage":{"input_tokens":1000000,"output_tokens":1000000,` +
				`"cost_usd":` + tc.costUSD + `,"cost_source":` + tc.costSource + `}}
				]}`
			ps, ok := parseSession([]byte(meta), nil)
			if !ok {
				t.Fatal("parseSession failed")
			}
			mu := ps.Info.ModelUsage[0].TokenUsage
			if mu.CostUSD == nil || *mu.CostUSD != 18.0 || mu.CostSource != "estimated" {
				t.Errorf("bucket cost = %+v/%q, want 18.0/estimated (unusable reported cost re-priced)", mu.CostUSD, mu.CostSource)
			}
		})
	}
}

