// TestIntegrationMyActivityCostGuardedByPayloadPhase proves cost_usd/cost_source
// travel under the same payload_hydrated/payload_seq freshness gate as the token
// columns (mirrors TestIntegrationPayloadPhaseGuardRejectsLateSkeleton in
// store_state_test.go). Before this test, cost used a plain EXCLUDED overwrite: a
// stale, out-of-order redelivery of the commit-first (nil cost) skeleton event —
// documented above this upsert as a real race under concurrent NATS redelivery —
// could silently null out an already-correct hydrated cost, even though every
// sibling payload column on the same row stayed protected.
func TestIntegrationMyActivityCostGuardedByPayloadPhase(t *testing.T) {
	_, st := openTest(t)
	ctx := context.Background()
	now := time.Now().UTC().Truncate(time.Second)

	hydratedCost := 7.25
	hydrated := MyActivityRow{
		AccountID: uid("acc1"), Type: "checkpoint", RepoID: uid("r1"), Jurisdiction: "us",
		SHA: hsha("sha1"), CheckpointID: "cp-race", CommittedAt: now,
		Agent: "codex", HasCheckpoint: true, PayloadHydrated: true, StateSeq: 500,
		InputTokens: 101, OutputTokens: 202,
		CostUSD: &hydratedCost, CostSource: "reported",
	}
	if err := st.UpsertMyActivity(ctx, hydrated); err != nil {
		t.Fatalf("upsert hydrated: %v", err)
	}

	// The race in the finding: a commit-first skeleton (no payload, no cost)
	// redelivered AFTER the hydrated event, with a higher raw stream sequence
	// than the hydrated row carried, simulating hydration racing ahead of a
	// skeleton with a lower phase but a higher home-stream position.
	lateSkeleton := MyActivityRow{
		AccountID: uid("acc1"), Type: "checkpoint", RepoID: uid("r1"), Jurisdiction: "us",
		SHA: hsha("sha1"), CheckpointID: "cp-race", CommittedAt: now,
		Agent: "unknown", HasCheckpoint: true, PayloadHydrated: false, StateSeq: 900,
	}
	if err := st.UpsertMyActivity(ctx, lateSkeleton); err != nil {
		t.Fatalf("upsert late skeleton: %v", err)
	}
	if got := oneCheckpointRow(t, st, uid("acc1"), "cp-race"); got.CostUSD == nil || *got.CostUSD != hydratedCost || got.CostSource != "reported" {
		t.Errorf("late lower-phase skeleton nulled the hydrated cost: got %v/%q, want %v/reported (unchanged)", got.CostUSD, got.CostSource, hydratedCost)
	}
	// And the tokens the pre-existing gate already protected stayed put too, so
	// this proves cost now matches their behavior rather than diverging from it.
	if got := oneCheckpointRow(t, st, uid("acc1"), "cp-race"); got.InputTokens != 101 || got.OutputTokens != 202 {
		t.Errorf("tokens regressed alongside the cost check: got in=%d out=%d, want 101/202", got.InputTokens, got.OutputTokens)
	}

	// A genuinely later hydrated event (same phase, higher seq) still correctly
	// updates the cost — the gate blocks staleness, not legitimate progress.
	correctedCost := 9.99
	corrected := hydrated
	corrected.StateSeq = 700
	corrected.CostUSD = &correctedCost
	corrected.CostSource = "estimated"
	if err := st.UpsertMyActivity(ctx, corrected); err != nil {
		t.Fatalf("upsert corrected: %v", err)
	}
	if got := oneCheckpointRow(t, st, uid("acc1"), "cp-race"); got.CostUSD == nil || *got.CostUSD != correctedCost || got.CostSource != "estimated" {
		t.Errorf("legitimate same-phase higher-seq update was blocked: got %v/%q, want %v/estimated", got.CostUSD, got.CostSource, correctedCost)
	}
}

