func TestActivityAttributesToHomeJurisdiction(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us")
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo)) // the mirror lives in eu
	author := w.User(home)                // but the author is homed in us

	eu.Receives(events.Push(repo, w.Commit(author)))

