func TestActivityDedupsAcrossPlacements(t *testing.T) {
	w := harness.New(t)
	us, eu := w.Cell("us"), w.Cell("eu")
	repo := w.Repo()
	us.Receives(events.RepoCreated(repo))
	eu.Receives(events.RepoCreated(repo))
	author := w.User(us)

	commit := w.Commit(author)
	us.Receives(events.Push(repo, commit)) // one commit...
	eu.Receives(events.Push(repo, commit)) // ...reaching both placements

	w.Settle()
	us.AssertActivity(author, harness.Activity{Rows: 1, AttributedTo: repo}) // one row, not one per placement
}

