// home as two immediate forwards: an unknown/zero skeleton, then the hydrated
// agent/count payload. JetStream's production-like duplicate window must retain
// the enrichment as a distinct wire identity; the home store must finish with
// the hydrated values rather than the skeleton. Removing the checkpoint payload
// fingerprint makes this fail as unknown/0/0.
func TestCheckpointHydrationSurvivesCrossCellDedup(t *testing.T) {
	w := harness.New(t)
	home := w.Cell("us", harness.ActivityConsumerPaused())
	eu := w.Cell("eu")
	repo := w.Repo()
	eu.Receives(events.RepoCreated(repo))
	author := w.User(home)

	const checkpointID = "c0ffee01"
	at := time.Now().UTC().Add(-time.Hour).Truncate(time.Second)
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, false)) // commit-first skeleton
	eu.Receives(events.CheckpointActivity(repo, author, checkpointID, at, true))  // immediate hydration
	home.AssertQueuedActivityMessages(2)                                          // skeleton + hydration are distinct wire identities
	home.StartActivityConsumer()                                                  // consume after broker dedup chose what survived

	w.Settle()
	home.AssertCheckpointActivity(checkpointID, "claude", 1, 1)
}

