// AssertCheckpointActivityCost asserts the my_activity row this cell landed for
// checkpointID carries wantCostUSD/wantCostSource exactly. wantCostUSD == nil
// asserts the stored cost is NULL (either never forwarded, or sanitized away).
func (c *Cell) AssertCheckpointActivityCost(checkpointID string, wantCostUSD *float64, wantCostSource string) {
	c.w.t.Helper()
	var gotCostUSD *float64
	var gotCostSource string
	if err := c.userStore.Pool().QueryRow(context.Background(),
		`SELECT cost_usd, cost_source FROM my_activity
		 WHERE checkpoint_id = $1 AND type = 'checkpoint'`, checkpointID).
		Scan(&gotCostUSD, &gotCostSource); err != nil {
		c.w.t.Fatalf("%s read my_activity cost for checkpoint %s: %v", c.jur, checkpointID, err)
	}
	mismatch := (gotCostUSD == nil) != (wantCostUSD == nil) ||
		(gotCostUSD != nil && wantCostUSD != nil && *gotCostUSD != *wantCostUSD) ||
		gotCostSource != wantCostSource
	if mismatch {
		c.w.t.Fatalf("%s checkpoint %s cost = %v/%q; want %v/%q (cost lost, wrong, or not sanitized crossing cells?)",
			c.jur, checkpointID, floatPtrOrNil(gotCostUSD), gotCostSource, floatPtrOrNil(wantCostUSD), wantCostSource)
	}
}

func floatPtrOrNil(f *float64) any {
	if f == nil {
		return nil
	}
	return *f
}

