func TestParseSessionReportedCostOnAggregateTokenUsage(t *testing.T) {
	metaReported := `{"session_id":"s","agent":"claude","checkpoints_count":1,"model":"claude-sonnet-5",
		"token_usage":{"input_tokens":1000000,"output_tokens":1000000,"cost_usd":4.25,"cost_source":"reported"}}`
	ps, ok := parseSession([]byte(metaReported), nil)
	if !ok {
		t.Fatal("parseSession failed")
	}
	if tu := ps.Info.TokenUsage; tu == nil || tu.CostUSD == nil || *tu.CostUSD != 4.25 || tu.CostSource != "reported" {
		t.Errorf("session cost = %+v, want 4.25/reported (aggregate block, no model_usage)", ps.Info.TokenUsage)
	}

	metaNoCost := `{"session_id":"s","agent":"claude","checkpoints_count":1,"model":"claude-sonnet-5",
		"token_usage":{"input_tokens":1000000,"output_tokens":1000000}}`
	psE, ok := parseSession([]byte(metaNoCost), nil)
	if !ok {
		t.Fatal("parseSession failed (no cost)")
	}
	if tu := psE.Info.TokenUsage; tu == nil || tu.CostUSD == nil || *tu.CostUSD != 18.0 || tu.CostSource != "estimated" {
		t.Errorf("session cost = %+v, want 18.0/estimated (aggregate fallback)", psE.Info.TokenUsage)
	}
}

