func TestBuildCheckpointRowCostSumOverRangeDropped(t *testing.T) {
	metaTemplate := `{"session_id":"%s","agent":"claude","checkpoints_count":1,
		"token_usage":{"input_tokens":1,"output_tokens":1,"cost_usd":60000000,"cost_source":"reported"}}`
	ps1, ok := parseSession([]byte(fmt.Sprintf(metaTemplate, "s1")), nil)
	if !ok {
		t.Fatal("parseSession s1 failed")
	}
	ps2, ok := parseSession([]byte(fmt.Sprintf(metaTemplate, "s2")), nil)
	if !ok {
		t.Fatal("parseSession s2 failed")
	}
	if ps1.Info.TokenUsage == nil || *ps1.Info.TokenUsage.CostUSD != 6e7 {
		t.Fatalf("session cost not trusted as expected: %+v", ps1.Info.TokenUsage)
	}

	cp := buildCheckpointRow("r1", "cp-overflow", &checkpointSummary{}, []parsedSession{ps1, ps2}, true)
	if cp.CostUSD != nil {
		t.Errorf("checkpoint cost_usd = %v, want nil (sum 1.2e8 overflows NUMERIC(14,6), must not fault the INSERT)", *cp.CostUSD)
	}
	if cp.CostSource != "" {
		t.Errorf("checkpoint cost_source = %q, want \"\" alongside the dropped cost", cp.CostSource)
	}
}

