cd /Users/suhaan/devenv/pr-merge/api-299
cp internal/store/sessions.go /tmp/sessions.go.bak
python3 - <<'PYEOF'
with open('internal/store/sessions.go') as f:
    content = f.read()
new = '''	if hasCost {
		// Each contributing checkpoint's cost already passed ValidCostUSD
		// individually, but their sum here can still overflow the
		// sessions.cost_usd NUMERIC(14,6) column (several checkpoints each < 1e8
		// summing to >= 1e8) — re-validate the sum itself rather than writing it
		// straight through and faulting the upsert on INSERT.
		row.costUSD, row.costSource = SanitizeCost(&costSum, CollapseCostSource(costSources))
	}'''
old = '''	if hasCost {
		row.costUSD = &costSum
		row.costSource = CollapseCostSource(costSources)
	}'''
assert new in content
content = content.replace(new, old)
with open('internal/store/sessions.go', 'w') as f:
    f.write(content)
PYEOF
mise run build 2>&1 | tail -5
go test ./internal/store/... -run TestAggregateSessionCostSumOverRangeDropped -v 2>&1 | tail -10
